'use client';

/**
 * The land office.
 *
 * A map of the whole region, with every plot on it in its place. The land is
 * painted from the plots themselves — each one's territory takes the colour of
 * its biome — so the desert really is out west and the fen really is down by
 * the southern water, and choosing where to settle is a decision about a place
 * rather than a scroll through a list of cards.
 *
 * Selecting a plot brings up its real terrain, generated by the same code that
 * will run the world once it is claimed, so the ground shown is the ground you
 * get.
 *
 * Claims and listings are honest about where they stand: with no registry
 * contract deployed they are recorded in this browser, and the panel says so
 * rather than showing a transaction that bought nothing.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { defaultWorldName } from '@/lib/simulation';
import {
  CHART_COUNT, HOME_CHART_INDEX, chartName, chartRoom, drawPlotPreview, drawRegionMap, islandsFor,
  loadPlayer, marketPlots, prospectPlot, savePlayer, usedSlots,
  type ClaimedWorld, type PlayerRecord, type Plot,
} from '@/lib/world/plots';
import { ACTIVE_CHAIN, TOKEN, claimPlot, tokenLive } from '@/lib/chain/emerge';
import { LOCAL_TEST_ALLOCATION, PROSPECT_COST_EMERGE } from '@/lib/chain/vault';
import { WalletPicker, useWallet } from './WalletPicker';

function PlotPreview({ seed }: { seed: number }) {
  const ref = useRef<HTMLCanvasElement | null>(null);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    // Generation takes a few tens of milliseconds; yielding a frame first keeps
    // the panel from appearing after a visible stall when the selection changes.
    const id = requestAnimationFrame(() => drawPlotPreview(canvas, seed));
    return () => cancelAnimationFrame(id);
  }, [seed]);
  return <canvas ref={ref} width={320} height={180} className="plot-canvas" />;
}

/**
 * The region.
 *
 * The canvas is painted once per set of plots and never re-rendered by React;
 * the markers are real buttons laid over it, so they can be tabbed to, focused
 * and read by a screen reader instead of being pixels with a hit test.
 */
function RegionMap({ plots, selected, chart, onSelect }: {
  plots: Plot[];
  selected: Plot | null;
  chart: number;
  onSelect: (plot: Plot) => void;
}) {
  const ref = useRef<HTMLCanvasElement | null>(null);
  useEffect(() => {
    if (ref.current) drawRegionMap(ref.current, plots, chart);
  }, [plots, chart]);

  return (
    <div className="region">
      <canvas ref={ref} width={900} height={570} className="region-canvas" aria-hidden />
      <div className="region-pins">
        {/* Every island is named, surveyed or not: an empty coast the player
            can see is what makes prospecting somewhere to go. */}
        {islandsFor(chart).map((island) => (
          <span
            key={island.name}
            className="island-name"
            // Below the island, where the markers are not.
            style={{ left: `${island.x * 100}%`, top: `${(island.y + island.ry * 0.92) * 100}%` }}
          >
            {island.name}
          </span>
        ))}
        {plots.map((plot) => (
          <button
            key={plot.id}
            // A marker on the right-hand side of the map hangs its label to the
            // left, or it runs off the edge.
            className={`region-pin ${plot.biome} ${plot.mapX > 0.66 ? 'flip' : ''} ${plot.seed === selected?.seed ? 'selected' : ''}`}
            style={{ left: `${plot.mapX * 100}%`, top: `${plot.mapY * 100}%` }}
            onClick={() => onSelect(plot)}
            aria-pressed={plot.seed === selected?.seed}
          >
            <span className="pin-dot" aria-hidden />
            <span className="pin-label">
              <b>{plot.region}</b>
              {/* The biome only on the one being looked at. Nine markers each
                  carrying two lines of text is more label than map. */}
              {plot.seed === selected?.seed && <em>{plot.biomeLabel}</em>}
            </span>
          </button>
        ))}
      </div>
      <div className="region-legend">
        <span>
          {plots.length} {plots.length === 1 ? 'plot' : 'plots'} surveyed on {islandsFor(chart).length} islands
        </span>
        <span>{plots.length ? 'Tap a marker to inspect the land' : 'Nothing here has been surveyed yet'}</span>
      </div>
    </div>
  );
}

export default function PlotSelect({ onEnter }: { onEnter: (world: ClaimedWorld) => void }) {
  const [player, setPlayer] = useState<PlayerRecord | null>(null);
  const [chart, setChart] = useState(HOME_CHART_INDEX);
  const [selectedSeed, setSelectedSeed] = useState<number | null>(null);
  const [name, setName] = useState('');
  const { wallet } = useWallet();
  const [claiming, setClaiming] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  // On a phone the map and the claim panel cannot both be on screen, so the
  // panel becomes a sheet that the map opens.
  const [sheetOpen, setSheetOpen] = useState(false);
  const configured = tokenLive();

  useEffect(() => { setPlayer(loadPlayer()); }, []);

  const plots = useMemo(() => (player ? marketPlots(player, chart) : []), [player, chart]);
  const room = useMemo(() => (player ? chartRoom(player, chart) : { capacity: 0, used: 0, free: 0 }), [player, chart]);
  const selected: Plot | null = plots.find((p) => p.seed === selectedSeed) ?? plots[0] ?? null;

  const choose = useCallback((plot: Plot) => {
    setSelectedSeed(plot.seed);
    setSheetOpen(true);
  }, []);

  const prospect = useCallback(() => {
    if (!player) return;
    if (player.ledger.balance < PROSPECT_COST_EMERGE) {
      setNotice(`Prospecting costs ${PROSPECT_COST_EMERGE.toLocaleString()} ${TOKEN.ticker}.`);
      return;
    }
    // Land is finite. When a chart is surveyed out the answer is to sail to
    // another one, not to stack another marker on the same skerry.
    const found = prospectPlot(chart, usedSlots(player, chart));
    if (!found) {
      setNotice(`Every island on ${chartName(chart)} has been surveyed. Sail to another chart to find new land.`);
      return;
    }
    const next: PlayerRecord = {
      ...player,
      ledger: { ...player.ledger, balance: player.ledger.balance - PROSPECT_COST_EMERGE },
      prospected: [...player.prospected, { seed: found.seed, chart: found.chart, slot: found.slot }],
    };
    savePlayer(next);
    setPlayer(next);
    setSelectedSeed(found.seed);
    setSheetOpen(true);
    setNotice(`Surveyed ${found.region} on ${found.island} — ${found.biomeLabel.toLowerCase()}.`);
  }, [player, chart]);

  const sail = useCallback((delta: number) => {
    setChart((c) => (c + delta + CHART_COUNT) % CHART_COUNT);
    setSelectedSeed(null);
    setSheetOpen(false);
    setNotice(null);
  }, []);

  const claim = useCallback(async () => {
    if (!selected) return;
    setClaiming(true);
    setNotice(null);
    const worldName = name.trim() || defaultWorldName(selected.seed);
    const result = await claimPlot({
      seed: selected.seed,
      region: selected.region,
      worldName,
      price: selected.price,
      address: wallet.address,
    });
    setClaiming(false);
    if (result.reason) setNotice(result.reason);
    onEnter({
      seed: selected.seed,
      name: worldName,
      region: selected.region,
      price: selected.price,
      claimedAt: Date.now(),
      owner: wallet.address,
      txHash: result.txHash,
    });
  }, [name, selected, wallet.address, onEnter]);

  const unlist = useCallback((seed: number) => {
    if (!player) return;
    const next = { ...player, listings: player.listings.filter((l) => l.seed !== seed) };
    savePlayer(next);
    setPlayer(next);
  }, [player]);

  if (!player) return <main className="land-office" />;

  return (
    <main className="land-office">
      <div className="land-inner">
        <header className="land-head">
          <div className="brand-line">
            <div className="brand-mark">✦</div>
            <div>
              <div className="wordmark">EMERGE</div>
              <div className="tagline">THE AI WORLD</div>
            </div>
          </div>
          <p className="land-intro">
            Every plot is a world waiting to happen, and no two are the same land. Claim one with
            {' '}{TOKEN.ticker}, give it a name, and the beings who live there will call it that.
          </p>
          <div className="land-head-side">
            <div className="land-balance">
              <span>YOUR BALANCE</span>
              <b>{Math.floor(player.ledger.balance).toLocaleString()}</b>
              <em>{TOKEN.ticker}</em>
            </div>
            <button
              className="ghost prospect"
              onClick={prospect}
              disabled={player.ledger.balance < PROSPECT_COST_EMERGE || room.free === 0}
            >
              {room.free === 0
                ? 'This chart is fully surveyed'
                : `Prospect new land · ${PROSPECT_COST_EMERGE.toLocaleString()} ${TOKEN.ticker}`}
            </button>
          </div>
        </header>

        {/* Where in the world you are looking. Each chart holds a fixed number
            of plots; when it is full the only way to new land is to sail. */}
        <nav className="charts">
          <button className="ghost" onClick={() => sail(-1)} aria-label="Previous chart">‹</button>
          <div className="chart-name">
            <b>{chartName(chart)}</b>
            <em>
              {room.used} of {room.capacity} plots surveyed
              {room.free === 0 ? ' · nothing left to find here' : ` · room for ${room.free} more`}
            </em>
          </div>
          <button className="ghost" onClick={() => sail(1)} aria-label="Next chart">›</button>
        </nav>

        <div className="land-body">
          <RegionMap plots={plots} selected={selected} chart={chart} onSelect={choose} />

          {!selected ? (
            <aside className="land-claim empty">
              <span className="eyebrow">UNSURVEYED</span>
              <h2>{chartName(chart)}</h2>
              <p className="muted">
                Nobody has set foot on these islands. There is room for {room.capacity} settlements out
                here; survey one to see what the land is made of.
              </p>
              <button
                className="claim-button"
                onClick={prospect}
                disabled={player.ledger.balance < PROSPECT_COST_EMERGE}
              >
                Survey a plot · {PROSPECT_COST_EMERGE.toLocaleString()} {TOKEN.ticker}
              </button>
              {notice && <p className="warn">{notice}</p>}
            </aside>
          ) : (
          <aside className={`land-claim ${sheetOpen ? 'open' : ''}`}>
            <button className="sheet-close" onClick={() => setSheetOpen(false)} aria-label="Back to the map">×</button>
            <span className="eyebrow">CLAIM</span>
            <h2>{selected.region}</h2>
            <div className="plot-traits">
              <span className={`biome-tag ${selected.biome}`}>{selected.biomeLabel}</span>
              <span>{selected.island}</span>
              <span>{selected.population} beings</span>
            </div>

            <PlotPreview seed={selected.seed} />
            <p className="muted">{selected.blurb}</p>

            <span className="eyebrow">TRADES THIS LAND SUPPORTS</span>
            <div className="plot-traits">
              {selected.trades.map((t) => <span key={t}>{t}</span>)}
            </div>

            <label className="name-field">
              <span>NAME YOUR WORLD</span>
              <input
                value={name}
                maxLength={24}
                placeholder={defaultWorldName(selected.seed)}
                onChange={(e) => setName(e.target.value)}
              />
            </label>

            <div className="claim-price">
              <span>PRICE</span>
              <b>{selected.price}</b>
              <em>{TOKEN.ticker}</em>
            </div>

            <div className="claim-wallet"><WalletPicker compact /></div>

            <button className="claim-button" onClick={claim} disabled={claiming}>
              {claiming ? 'Claiming…' : `Claim ${selected.region}`}
            </button>

            {player.listings.length > 0 && (
              <>
                <span className="eyebrow">YOUR LISTINGS</span>
                <div className="listing-list">
                  {player.listings.map((listing) => (
                    <div key={listing.seed} className="listing-row">
                      <span>{listing.region}</span>
                      <b>{listing.price.toLocaleString()} {TOKEN.ticker}</b>
                      <button className="ghost" onClick={() => unlist(listing.seed)}>Withdraw</button>
                    </div>
                  ))}
                </div>
                <p className="muted small">
                  Resale between players needs the plot registry on {ACTIVE_CHAIN.label}. Until it is
                  deployed a listing is recorded in this browser and no one else can see it.
                </p>
              </>
            )}

            {!configured && (
              <p className="muted small">
                This build talks to {ACTIVE_CHAIN.label} (chain {ACTIVE_CHAIN.chainId}), but the
                {' '}{TOKEN.ticker} contract is not deployed there yet, so claims are recorded in this browser
                rather than on chain and you start with a local development allocation of
                {' '}{LOCAL_TEST_ALLOCATION.toLocaleString()} {TOKEN.ticker}. Neither is a token transfer.
              </p>
            )}
            {notice && <p className="warn">{notice}</p>}
          </aside>
          )}
        </div>
      </div>
    </main>
  );
}
